// 1차원 배열 하나로 0/1 배낭 (각 물건은 한 번만)
for (int i = 1; i <= n; i++)
    for (int c = W; c >= w[i]; c--)          // 뒤에서부터
        dp[c] = max(dp[c], dp[c - w[i]] + v[i]);

// 앞에서부터 돌면? (같은 물건을 여러 번 쓸 수 있게 된다)
for (int i = 1; i <= n; i++)
    for (int c = w[i]; c <= W; c++)          // 앞에서부터
        dp[c] = max(dp[c], dp[c - w[i]] + v[i]);

// 한 번에 1~k칸 오를 때 n칸에 이르는 방법의 수
// S[i] = dp[0] + … + dp[i-1] (누적 합)
dp[0] = 1; S[0] = 0; S[1] = 1;
for (int i = 1; i <= n; i++) {
    dp[i] = S[i] - S[max(0, i - k)];         // dp[i-k] + … + dp[i-1]
    S[i + 1] = S[i] + dp[i];
}

// 사탕 j개를 아이 i명에게 나눠 주는 방법의 수 (한 명당 0~c개)
// dp[i][j] = dp[i-1][j] + dp[i-1][j-1] + … + dp[i-1][j-c]
for (int i = 1; i <= kids; i++) {
    P[0] = 0;
    for (int j = 0; j <= tot; j++) P[j + 1] = P[j] + dp[i - 1][j];   // 이전 줄의 누적 합
    for (int j = 0; j <= tot; j++) dp[i][j] = P[j + 1] - P[max(0, j - c)];
}

// 0번 칸에서 출발해 한 번에 1~k칸 앞으로 뛰어 n-1번 칸에 도착할 때, 밟은 칸 값의 합의 최댓값
// dp[i] = max(dp[i-k], …, dp[i-1]) + a[i]  — 덱으로 구간 최댓값을 유지
deque<int> dq; dp[0] = a[0]; dq.push_back(0);
for (int i = 1; i < n; i++) {
    while (dq.front() < i - k) dq.pop_front();           // 범위를 벗어난 칸
    dp[i] = dp[dq.front()] + a[i];
    while (!dq.empty() && dp[dq.back()] <= dp[i]) dq.pop_back();
    dq.push_back(i);
}

// tails[L]: 길이 L+1인 증가 부분 수열의 끝값 가운데 가장 작은 값
vector<int> tails;
for (int x : a) {
    auto it = lower_bound(tails.begin(), tails.end(), x);   // x 이상인 첫 위치
    if (it == tails.end()) tails.push_back(x);
    else *it = x;
}
// LIS의 길이는 tails.size()

